const items = $input.all();
const processed = [];
const candidateItems = $('Filter Out Existing Duplicates').all();

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const candidate = candidateItems[i]?.json || {};

  let aiRes = {};
  try {
    let rawText = item.json.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
    rawText = rawText.replace(/^```json\s*/i, '').replace(/\s*```$/i, '').trim();
    aiRes = JSON.parse(rawText);
  } catch (err) {
    aiRes = {
      is_potential_client: false,
      intent_type: 'IRRELEVANT',
      is_provider: false,
      is_fulltime_job: false,
      need: 'Unknown',
      urgency: 'UNKNOWN',
      budget_signal: false,
      qualification_reason: 'JSON parse error from Gemini AI: ' + err.message
    };
  }

  processed.push({
    json: {
      ...candidate,
      ai_result: aiRes
    }
  });
}

return processed;

const items = $input.all();
const scoredLeads = [];

for (const item of items) {
  const data = item.json;
  const ai = data.ai_result || {};

  let score = 0;

  if (ai.is_potential_client && !ai.is_provider && !ai.is_fulltime_job) {
    if (['PROJECT_REQUEST', 'OUTSOURCING_NEED'].includes(ai.intent_type)) score += 30;
    else if (ai.intent_type === 'VENDOR_RECOMMENDATION') score += 20;
    else if (ai.intent_type === 'BUSINESS_PROBLEM') score += 15;

    if (ai.need && ai.need.length > 5) score += 15;
    if (ai.urgency === 'HIGH') score += 15;
    if (ai.budget_signal) score += 10;
  }

  if (ai.is_fulltime_job) score -= 50;
  if (ai.is_provider) score -= 50;
  if (['GENERAL_INQUIRY', 'MARKETING_CONTENT'].includes(ai.intent_type)) score -= 30;
  if (ai.intent_type === 'IRRELEVANT' || !ai.is_potential_client) score -= 50;

  score = Math.max(0, Math.min(100, score));

  let temp = 'IRRELEVANT';
  if (score >= 80) temp = 'HOT';
  else if (score >= 50) temp = 'WARM';
  else if (score >= 20) temp = 'COLD';

  const safeString = (val) => val ? String(val).replace(/'/g, "''") : null;

  scoredLeads.push({
    json: {
      platform: data.platform || 'web',
      post_url: data.post_url,
      author_name: safeString(data.author_name),
      author_url: safeString(data.author_url),
      post_text: safeString(data.post_text),
      posted_at: data.posted_at || new Date().toISOString(),
      matched_keywords: JSON.stringify(data.matched_keywords || []),
      service_needed: safeString(ai.need),
      intent: ai.intent_type || 'IRRELEVANT',
      lead_score: score,
      lead_temperature: temp,
      urgency: ai.urgency || 'UNKNOWN',
      budget_signal: ai.budget_signal ? 'YES' : 'NO',
      business_type: 'SMB',
      qualification_reason: safeString(ai.qualification_reason),
      suggested_outreach_angle: safeString(ai.need ? `Provide specialized solutions for ${ai.need}` : 'Propose tech partnership'),
      status: 'NEW',
      post_text_hash: data.post_text_hash,
      is_qualified: ['HOT', 'WARM', 'COLD'].includes(temp)
    }
  });
}

return scoredLeads;

